#include "stage_data.hpp"
#include <fstream>
#include <cstdio>
int main(int argc,char**argv){try{assetCheck(argc==3,"Expected WBFS and sample output");WiiAssets disc(std::filesystem::u8path(argv[1]));unsigned archives=0,tables=0;size_t rows=0;for(const auto& file:disc.files){if(file.path.find("DemoSheet.arc")==std::string::npos||file.path.size()<4||file.path.substr(file.path.size()-4)!=".arc")continue;Rarc arc(disc.readFile(file.path));++archives;printf("Archive %s files%zu\n",file.path.c_str(),arc.files.size());for(const auto& entry:arc.files){if(entry.path.size()<5||entry.path.substr(entry.path.size()-5)!=".bcsv")continue;auto bytes=arc.readFile(entry.path);StageTable table{BinaryView(bytes)};table.validate();int part=table.find("PartName"),steps=table.find("TotalStep"),suspend=table.find("SuspendFlag");if(part<0||steps<0||suspend<0)continue;for(size_t r=0;r<table.rows;++r){auto name=table.read(r,part),duration=table.read(r,steps),flag=table.read(r,suspend);assetCheck(std::holds_alternative<std::string>(name)&&std::holds_alternative<uint32_t>(duration)&&std::holds_alternative<uint32_t>(flag),"Unexpected time sheet field types");}auto outputDir=std::filesystem::u8path(argv[2]).parent_path()/"retail-demo-times";std::filesystem::create_directories(outputDir);std::ofstream every(outputDir/std::filesystem::u8path(entry.path).filename(),std::ios::binary);every.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());assetCheck(bool(every),"Cannot save retail timeline");if(!tables&&table.rows){std::ofstream out(std::filesystem::u8path(argv[2]),std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());assetCheck(bool(out),"Cannot save time sample");printf("Sample %s:%s rows%zu bytes%zu\n",file.path.c_str(),entry.path.c_str(),table.rows,bytes.size());}++tables;rows+=table.rows;}}assetCheck(tables&&rows,"No retail timelines located");printf("PASS bounded retail timeline fields: %u demo archives, %u time tables, %zu rows; sample saved, not executed\n",archives,tables,rows);}catch(const std::exception&e){fprintf(stderr,"%s\n",e.what());return 1;}}



